import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Extremidades y trauma","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/limbs-and-trauma.md","filePath":"es/guide/combat/limbs-and-trauma.md"}'),d={name:"es/guide/combat/limbs-and-trauma.md"};function o(n,a,s,l,c,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="limbs-and-trauma" tabindex="-1">Extremidades y trauma <a class="header-anchor" href="#limbs-and-trauma" aria-label="Enlace permanente a &quot;Extremidades y trauma&quot;">​</a></h1><p><strong>Estado:</strong> Aceptado: separación de salud y trauma · Experimental: lesión local parcialmente integrada · Propuesto: lesiones ampliadas; penalizaciones funcionales pendientes.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Global Hits, integridad regional y estado de la armadura son distintos.</li><li>Local Trauma afecta a la región alcanzada; Disabled no significa amputación automática.</li><li>Recuperar salud no repara automáticamente una lesión local.</li></ul><p><span id="health-is-not-the-whole-story"></span><span id="recovery-is-still-an-experiment"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td>Global Hits</td><td>La salud global determina la supervivencia.</td></tr><tr><td>Regiones corporales</td><td>Cabeza, cuello, torso, cada brazo y cada pierna tienen integridad separada. Izquierda y derecha son las del objetivo.</td></tr><tr><td>Estados</td><td>Healthy (sano) → Wounded (herido) → Injured (lesionado) → Severe (grave) → Disabled (incapacitado) describe el daño acumulado.</td></tr><tr><td>Consecuencias</td><td>Registrar una lesión todavía no implica cojera, pérdida del arma o muerte instantánea. La consecuencia prevista para el brazo del escudo sigue pendiente.</td></tr><tr><td>Recuperación</td><td>Tratamientos, lesiones duraderas y control del sangrado siguen abiertos; las lesiones locales temporales actuales no son un sistema médico definitivo.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>La pérdida de salud y la curación son preocupaciones conocidas del combate</td><td>Conservar la supervivencia global y registrar por separado la región dañada.</td></tr><tr><td>Las vendas ayudan a curar</td><td>No asumir que recuperar salud también repara cualquier lesión local.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un brazo recibe golpes repetidos mientras el personaje aún conserva salud. Curar esa salud no restaura automáticamente la integridad del brazo ni repara sus mangas.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Armadura</a> · <a href="/Syrolands-Public/es/guide/combat/targeting-and-anatomy.html">Anatomía</a> · <a href="/Syrolands-Public/es/game-design/combat/disability.html">Incapacitación</a> · <a href="/Syrolands-Public/es/game-design/combat/damage.html">Daño</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/body-regions.html">Leer la especificación de diseño completa</a></p>',15)])])}const h=e(d,[["render",o]]);export{p as __pageData,h as default};
